   "source": [
    "parquet_folder <- \"/kaggle/input/datasets/kristenjelaena/taxi-trips\"\n",
    "\n",
    "\n",
    "files_2023 <- list.files(\n",
    "  parquet_folder, \n",
    "  pattern = \"yellow_tripdata_2023-.*\\\\.parquet$\", \n",
    "  full.names = TRUE\n",
    ")\n",
    "\n",
    "taxi_2023 <- map_dfr(files_2023, function(f) {\n",
    "  read_parquet(f) %>%\n",
    "    filter(trip_distance > 0, total_amount > 0) %>%\n",
    "    mutate(\n",
    "      pickup_datetime  = as_datetime(tpep_pickup_datetime),\n",
    "      dropoff_datetime = as_datetime(tpep_dropoff_datetime)\n",
    "    )\n",
    "})\n",
    "taxi_2023 <- taxi_2023 %>%\n",
    "mutate(month_year = format(pickup_datetime, \"%Y-%m\")) # or use year(month(pickup_datetime)) for year-month format\n",
    "\n",
    "# Get the number of months in the dataset (expected to be 12 for a full year)\n",
    "months_in_year <- n_distinct(taxi_2023$month_year)\n",
    "\n",
    "# We want a total of 1.2 million rows\n",
    "total_rows <- 1.2e6\n",
    "rows_per_month <- total_rows / months_in_year\n",
    "\n",
    "taxi_clean <- taxi_2023 %>%\n",
    "  mutate(\n",
    "    trip_duration_minutes =\n",
    "      as.numeric(difftime(dropoff_datetime, pickup_datetime, units = \"mins\")),\n",
    "    fare_per_mile = total_amount / trip_distance,\n",
    "    month   = factor(month(pickup_datetime)),\n",
    "    quarter = factor(quarter(pickup_datetime))\n",
    "  ) %>%\n",
    "  filter(trip_duration_minutes > 0)\n",
    "\n",
    "glimpse(taxi_clean)\n"
   ]
  },
