   "source": [
    "# Sample equal rows from each month\n",
    "taxi_sample <- taxi_clean %>%\n",
    "  group_by(month_year) %>%\n",
    "  sample_n(min(rows_per_month, n())) %>% # Ensure we don't sample more than the available rows in any month\n",
    "  ungroup()\n",
    "\n",
    "# View the sampled data\n",
    "glimpse(taxi_sample)"
   ]
