   "source": [
    "loess_taxi <- loess(total_amount ~ trip_distance, data=taxi_sample, span=0.4)\n",
    "\n",
    "ggplot(taxi_sample, aes(trip_distance, total_amount)) +\n",
    "  geom_point(alpha=0.02) +\n",
    "  geom_smooth(method=\"lm\", se=FALSE, color=\"blue\") +\n",
    "  geom_smooth(method=\"loess\", span=0.4, se=FALSE, color=\"red\") +\n",
    "  labs(title=\"Linear vs LOESS Fit\")\n",
    "\n",
    "rmse_lm <- rmse(lm_taxi, taxi_sample)\n",
    "rmse_loess <- rmse(loess_taxi, taxi_sample)\n",
    "rmse_lm\n",
    "rmse_loess"
   ]
  },
