    "infl <- augment(lm_taxi) %>%\n",
    "  mutate(cooks_d = cooks.distance(lm_taxi))\n",
    "top10 <- infl %>% arrange(desc(cooks_d)) %>% slice(1:10) %>% select(trip_distance, total_amount, cooks_d)\n",
    "top10\n",
    "\n",
    "robust_taxi <- lmrob(total_amount ~ trip_distance, data=taxi_sample)\n",
    "summary(robust_taxi)\n",
    "\n",
    "coef(lm_taxi)\n",
    "coef(robust_taxi)"
   ]
