   "source": [
    "quarter_models <- taxi_sample %>%\n",
    "  group_by(quarter) %>%\n",
    "  nest() %>%\n",
    "  mutate(model = map(data, ~ lm(total_amount ~ trip_distance, data=.x)))\n",
    "\n",
    "ggplot(taxi_sample, aes(trip_distance, total_amount, color=quarter)) +\n",
    "  geom_point(alpha=0.02) +\n",
    "  geom_smooth(method=\"lm\", se=FALSE) +\n",
    "  labs(title=\"Fare-Distance Relationship by Quarter\")"
   ]
